import{_ as d,o,c as t,aV as r}from"./chunks/framework.BkhZod2m.js";const s=JSON.parse('{"title":"Renderer 迁移准备度盘点","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/renderer-migration-readiness.md","filePath":"catalog/renderer-migration-readiness.md","lastUpdated":null}'),l={name:"catalog/renderer-migration-readiness.md"};function i(c,e,a,n,m,y){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="renderer-迁移准备度盘点" tabindex="-1">Renderer 迁移准备度盘点 <a class="header-anchor" href="#renderer-迁移准备度盘点" aria-label="Permalink to &quot;Renderer 迁移准备度盘点&quot;">​</a></h1><p>状态：当前参考（架构风险与未来任务路由）。本文件记录在“未来可能更换 UI 框架、但尚未确定目标框架和真实消费者”的前提下，各公共模块的迁移准备度。它不是实施计划、PRP 或发布承诺。</p><h2 id="当前决定" tabindex="-1">当前决定 <a class="header-anchor" href="#当前决定" aria-label="Permalink to &quot;当前决定&quot;">​</a></h2><ul><li>当前继续维护 Vue 3 + Element Plus implementation，不实施 Naive UI 或其他第二 renderer。</li><li>暂不改造 <code>@qynpm/form</code>，不新增第二套表单、<code>/element</code>、<code>/naive</code>、运行时 <code>framework</code> prop、provider 或 renderer 注册器。</li><li>不批量为简单组件增加 renderer 目录，不因未来可能迁移而重写已稳定组件。</li><li>新公共 interface 继续使用 Qy 自有语义和类型；不得扩大 Element Plus 类型、实例、私有 DOM/VNode/Node/Store、私有事件和 <code>--el-*</code> 的公共泄漏。</li><li>新组件只有在复杂受控状态、浮层/teleport/focus、递归节点、厂商回调、底层默认行为差异或真实第二实现存在时，才建立物理 adapter seam。</li><li>真正确定目标框架和首个消费者后，另立 ADR 与 PRP；实施顺序默认是基础控件 → form/table → patterns/shell → 业务组件。</li></ul><h2 id="尚未存在的多-renderer-入口" tabindex="-1">尚未存在的多 renderer 入口 <a class="header-anchor" href="#尚未存在的多-renderer-入口" aria-label="Permalink to &quot;尚未存在的多 renderer 入口&quot;">​</a></h2><p>当前没有 <code>@qynpm/form/element</code>、<code>@qynpm/form/naive</code>、<code>@qynpm/ui/naive</code>、运行时 <code>framework</code> prop/provider 或全局 renderer 注册器。<code>table-schema</code> 的 core/Element 目录也不等于已经公开第二 renderer 子路径。它们是未来可能的设计选项，不是当前可导入入口。</p><p>如果目标框架和真实消费者确定，优先保持现有 Qy interface：简单 UI 模块替换内部 implementation；form/table 等 schema 模块先抽共享 core，再评估同包子路径或独立 renderer 包。各包尚未实现项、推荐入口方向与启动条件统一见 <a href="./component-roadmap">公共组件现状与后续路线</a>。</p><h2 id="分级口径" tabindex="-1">分级口径 <a class="header-anchor" href="#分级口径" aria-label="Permalink to &quot;分级口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>含义</th></tr></thead><tbody><tr><td>大</td><td>公共类型、状态协议、实例、递归/浮层或跨包 renderer 与 Element Plus 深度耦合；未来需要专项设计和完整验收。</td></tr><tr><td>中</td><td>Qy interface 大体可保留，但交互、事件、样式、类型债务或组合组件需要明确适配。</td></tr><tr><td>小</td><td>公共 interface 已较稳定，未来主要替换内部 implementation。</td></tr><tr><td>无需专项改造</td><td>当前实现基本框架无关；底层依赖变化后只需集成回归。</td></tr></tbody></table><p>分级衡量的是未来迁移准备和改造成本，不表示现在要实施，也不等同于第二 renderer 本身的实现工作量。</p><h2 id="包级盘点" tabindex="-1">包级盘点 <a class="header-anchor" href="#包级盘点" aria-label="Permalink to &quot;包级盘点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包/模块</th><th>等级</th><th>当前事实与未来边界</th></tr></thead><tbody><tr><td><code>@qynpm/form</code></td><td>大</td><td><code>FormItemSet</code>、规则、<code>ElFormItem</code>、VNode 与 <code>getFormProps()</code> 仍绑定 Element Plus；当前暂缓。未来如确定切换，优先测试冻结行为，再在同一实现内渐进抽 core 和 Element renderer，不维护两套完整 schema 逻辑。</td></tr><tr><td><code>@qynpm/admin-shell</code> 的 Tabs、Topbar、Sidebar Navigation</td><td>大</td><td>递归菜单、标签状态、下拉浮层、图标和交互绑定当前实现；Shell 已冻结，无明确切换任务时不改。</td></tr><tr><td><code>@qynpm/product-preview</code></td><td>大</td><td>商品、工艺、SKU 和业务表单状态规模大；按业务模块迁移，不升级为通用 renderer 工程。</td></tr><tr><td><code>@qynpm/qy-address-dialog</code></td><td>大</td><td>地址解析、表单、弹窗、受控状态和公开方法集中；修改前还需先裁决大小写重复目录的权威来源。</td></tr><tr><td><code>@qynpm/table</code></td><td>当前结构小、第二实现大</td><td>已有 Qy facade 与 <code>ElementTableRenderer</code>，只剩少量门面实现债务；真正增加第二表格 renderer 仍是大型任务。</td></tr><tr><td><code>@qynpm/table-schema</code></td><td>当前结构小、第二实现大</td><td>已拆 core 与 <code>element-plus</code> 目录；未来新增列、编辑单元格和事件适配工作量大，但不需要先重构 core。</td></tr><tr><td><code>@qynpm/admin-patterns</code></td><td>中</td><td>Drawer、FormPanel、Pagination 已有 renderer seam；Page、Search、Detail、Status 与 ActionBar 基本框架无关。</td></tr><tr><td><code>@qynpm/pickers</code></td><td>中到大</td><td>ProductPicker 为大；Staff、Shop、CategoryTree、ProductCategoryMenu 为中；QuoteOrder 为小。保留业务请求和字段协议，未来只替换交互 implementation。</td></tr><tr><td><code>@qynpm/admin-framework</code></td><td>无需专项改造</td><td>路由、权限、菜单和运行时状态不依赖 Element Plus。</td></tr><tr><td><code>@qynpm/admin-theme</code></td><td>无需专项改造</td><td>Qy tokens 保持稳定；未来为目标框架增加 token 映射。</td></tr><tr><td><code>@qynpm/hooks</code></td><td>无需专项改造</td><td>feedback 等能力使用宿主 runtime 思路，不应绑定具体 UI 实例。</td></tr></tbody></table><h2 id="qynpm-ui-全量分类" tabindex="-1"><code>@qynpm/ui</code> 全量分类 <a class="header-anchor" href="#qynpm-ui-全量分类" aria-label="Permalink to &quot;`@qynpm/ui` 全量分类&quot;">​</a></h2><h3 id="大" tabindex="-1">大 <a class="header-anchor" href="#大" aria-label="Permalink to &quot;大&quot;">​</a></h3><ul><li><code>QyDialog</code></li><li><code>QyCascader</code></li><li><code>QyTree</code></li><li><code>QyTreeSelect</code></li><li><code>QySelectionDialog</code></li><li><code>QyLegacySelectionDialog</code></li><li><code>QyUpload</code></li><li><code>QyRemarkImage</code></li></ul><p>这些模块包含浮层、递归节点、受控状态、实例方法、上传状态或复杂事件协议，未来必须逐项冻结行为并验收真实 DOM/交互。</p><h3 id="中" tabindex="-1">中 <a class="header-anchor" href="#中" aria-label="Permalink to &quot;中&quot;">​</a></h3><ul><li><code>QyAutocomplete</code></li><li><code>QyCollapse</code></li><li><code>QyCollapseItem</code></li><li><code>QyDatePicker</code></li><li><code>QyImage</code></li><li><code>QyImagePreview</code></li><li><code>QyImageUpload</code></li><li><code>QyInput</code></li><li><code>QyInputNumber</code></li><li><code>QyMoneyInput</code></li><li><code>QyPopover</code></li><li><code>QyRemoteSelect</code></li><li><code>QyScrollbar</code></li><li><code>QySearchInput</code></li><li><code>QySelect</code></li><li><code>QyTabs</code></li><li><code>QyTabPane</code></li><li><code>QyTooltip</code></li></ul><p><code>QyInput</code> 与 <code>QyInputNumber</code> 的公开声明仍存在已登记的 Element Plus 类型泄漏；后续按模块、以兼容性为前提治理，不据此批量修改。</p><h3 id="小" tabindex="-1">小 <a class="header-anchor" href="#小" aria-label="Permalink to &quot;小&quot;">​</a></h3><ul><li><code>QyAlert</code></li><li><code>QyAside</code></li><li><code>QyAvatar</code></li><li><code>QyBadge</code></li><li><code>QyCard</code></li><li><code>QyCheckbox</code></li><li><code>QyCheckboxGroup</code></li><li><code>QyCol</code></li><li><code>QyContainer</code></li><li><code>QyDescriptions</code></li><li><code>QyDescriptionsItem</code></li><li><code>QyDivider</code></li><li><code>QyEmpty</code></li><li><code>QyLink</code></li><li><code>QyMain</code></li><li><code>QyProgress</code></li><li><code>QyRadio</code></li><li><code>QyRadioGroup</code></li><li><code>QyRow</code></li><li><code>QySkeleton</code></li><li><code>QySkeletonItem</code></li><li><code>QyStatistic</code></li><li><code>QyStep</code></li><li><code>QySteps</code></li><li><code>QySwitch</code></li><li><code>QyTag</code></li></ul><h3 id="无需专项改造" tabindex="-1">无需专项改造 <a class="header-anchor" href="#无需专项改造" aria-label="Permalink to &quot;无需专项改造&quot;">​</a></h3><ul><li><code>QyActionBar</code></li><li><code>QyButton</code></li><li><code>QyDropdown</code></li><li><code>QyFilePicker</code></li><li><code>QyFormSection</code></li><li><code>QyIcon</code></li><li><code>QyMenuActions</code></li><li><code>QyRecordQuoteSearch</code></li><li><code>QyTableColumnSettings</code></li></ul><p>这些模块仍要在依赖的 Qy 控件或宿主 runtime 更换后做集成回归，但不需要为 UI 框架切换单独建立 renderer。</p><h2 id="新组件设计检查" tabindex="-1">新组件设计检查 <a class="header-anchor" href="#新组件设计检查" aria-label="Permalink to &quot;新组件设计检查&quot;">​</a></h2><p>规划新组件时按以下顺序判断：</p><ol><li>先确认真实消费者和稳定 Qy interface，不因未来可能性扩展功能。</li><li>Element Plus 可以作为当前内部 implementation，但公共声明不得新增厂商类型或实例。</li><li>简单展示和薄交互直接实现即可；物理 renderer 目录不是默认模板。</li><li>复杂受控状态、浮层/焦点、递归、厂商回调对象或默认行为差异必须在 PRP 中明确 adapter seam 和独立验收矩阵。</li><li>没有真实第二 renderer 时，不增加框架子路径、动态切换器或额外 peer dependency。</li><li>如果未来正式切换，先核对目标框架、首个消费者、包级 peer dependency 与发布方式，再决定同包子路径还是独立 renderer 包。</li></ol><p>返回 <a href="./../README">文档地图</a> 或 <a href="./component-lifecycle">公共能力生命周期</a>。</p>',28)])])}const h=d(l,[["render",i]]);export{s as __pageData,h as default};
